B.arw=new A.ab("\u042f \u043d\u0430\u043f\u0438\u0441\u0430\u043b \u0434\u0440\u0443\u0433\u0443\u044e \u0444\u043e\u0440\u043c\u0443 \u2014 \u043f\u043e\u0447\u0435\u043c\u0443 \u043d\u0435 \u043e\u0448\u0438\u0431\u043a\u0430?","\xabBr\xfcder\xbb \u0432\u043c\u0435\u0441\u0442\u043e \xabBruder\xbb \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u0441\u043b\u043e\u0432\u043e \u0432\u044b \u0432\u0441\u043f\u043e\u043c\u043d\u0438\u043b\u0438; \u043f\u0440\u043e\u043c\u0430\u0445 \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u0444\u043e\u0440\u043c\u0435. \u0421\u0442\u0443\u043f\u0435\u043d\u044c \u0437\u0430 \u0442\u0430\u043a\u043e\u0439 \u043e\u0442\u0432\u0435\u0442 \u043d\u0435 \u0440\u0430\u0441\u0442\u0451\u0442, \u043d\u043e \u0438 \u0432\u043d\u0438\u0437 \u043d\u0435 \u0438\u0434\u0451\u0442, \u0438 \u0441\u043b\u043e\u0432\u043e \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0447\u0435\u0440\u0435\u0437 \u0447\u0430\u0441, \u0430 \u043d\u0435 \u0437\u0430\u0432\u0442\u0440\u0430: \u044d\u0442\u043e \u043d\u0435 \u043f\u0440\u043e\u0432\u0430\u043b, \u0430 \u043f\u043e\u0432\u043e\u0434 \u0432\u0437\u0433\u043b\u044f\u043d\u0443\u0442\u044c \u0435\u0449\u0451 \u0440\u0430\u0437, \u043f\u043e\u043a\u0430 \u0432\u044b \u043f\u043e\u043c\u043d\u0438\u0442\u0435, \u043a\u0430\u043a \u0431\u043b\u0438\u0437\u043a\u043e \u0431\u044b\u043b\u0438.")
B.arS=new A.ab("\u042f \u0432\u043f\u0438\u0441\u0430\u043b \u0441\u0438\u043d\u043e\u043d\u0438\u043c, \u0438 \u043e\u043d \u0442\u043e\u0436\u0435 \u043f\u043e\u0434\u0445\u043e\u0434\u0438\u0442","\u0415\u0441\u043b\u0438 \u044d\u0442\u043e \u0441\u043b\u043e\u0432\u043e \u2014 \u0442\u043e\u0436\u0435 \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0430 \u043a\u043e\u043b\u043e\u0434\u044b \u0441 \u0442\u0435\u043c \u0436\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435\u043c, \u0432\u0430\u043c \u0441\u043a\u0430\u0436\u0443\u0442, \u043a\u0430\u043a\u043e\u0435 \u0441\u043b\u043e\u0432\u043e \u0437\u0434\u0435\u0441\u044c \u0442\u0440\u0435\u043d\u0438\u0440\u0443\u0435\u0442\u0441\u044f, \u0438 \u043e\u0448\u0438\u0431\u043a\u043e\u0439 \u044d\u0442\u043e \u043d\u0435 \u0431\u0443\u0434\u0435\u0442: \u0441\u0442\u0443\u043f\u0435\u043d\u044c \u043e\u0441\u0442\u0430\u043d\u0435\u0442\u0441\u044f \u043d\u0430 \u043c\u0435\u0441\u0442\u0435, \u0430 \u0441\u043b\u043e\u0432\u043e \u0432\u0435\u0440\u043d\u0451\u0442\u0441\u044f \u0447\u0435\u0440\u0435\u0437 \u0447\u0430\u0441. \u0420\u0430\u043c\u043a\u0438, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0440\u0430\u0437\u0434\u0435\u043b\u044f\u0435\u0442 \u0432\u0437\u0430\u0438\u043c\u043e\u0437\u0430\u043c\u0435\u043d\u044f\u0435\u043c\u0443\u044e \u043f\u0430\u0440\u0443, \u0447\u0430\u0449\u0435 \u0432\u0441\u0435\u0433\u043e \u043f\u0440\u043e\u0441\u0442\u043e \u043d\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u0435\u0442.\n\n\u0415\u0441\u043b\u0438 \u0436\u0435 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0432\u0441\u0451-\u0442\u0430\u043a\u0438 \u0437\u0430\u0441\u0447\u0438\u0442\u0430\u043b\u043e \u043f\u0440\u043e\u043c\u0430\u0445, \u0430 \u0432\u0430\u0448\u0435 \u0441\u043b\u043e\u0432\u043e \u0432 \u043f\u0440\u043e\u043f\u0443\u0441\u043a \u0432\u0441\u0442\u0430\u0451\u0442 \u2014 \u043d\u0430\u0436\u043c\u0438\u0442\u0435 \xab\u041c\u043e\u0451 \u0441\u043b\u043e\u0432\u043e \u0442\u043e\u0436\u0435 \u043f\u043e\u0434\u0445\u043e\u0434\u0438\u0442\xbb. \u042d\u0442\u0430 \u0441\u0442\u0440\u043e\u043a\u0430 \u0436\u0443\u0440\u043d\u0430\u043b\u0430 \u043f\u043e\u043c\u0435\u0442\u0438\u0442\u0441\u044f \u0441\u043f\u043e\u0440\u043d\u043e\u0439.")
B.aro=new A.ab("\u0423 \u043c\u0435\u043d\u044f \u043d\u0435\u0442 \u043d\u0435\u043c\u0435\u0446\u043a\u043e\u0439 \u043a\u043b\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u044b","\u0423\u043c\u043b\u0430\u0443\u0442\u044b \u043c\u043e\u0436\u043d\u043e \u043f\u0438\u0441\u0430\u0442\u044c \u0442\u0430\u043a \u0436\u0435, \u043a\u0430\u043a \u043f\u0438\u0448\u0435\u0442 \u0441\u0430\u043c \u043d\u0435\u043c\u0435\u0446\u043a\u0438\u0439 \u0431\u0435\u0437 \u043d\u0438\u0445: ae, oe, ue \u0438 ss. \xabfuer\xbb \u0437\u0430\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \xabf\xfcr\xbb, \xabStrasse\xbb \u2014 \u043a\u0430\u043a \xabStra\xdfe\xbb. \u041f\u0440\u043e\u043f\u0443\u0449\u0435\u043d\u043d\u044b\u0435 \u0442\u043e\u0447\u043a\u0438 \u2014 \xabfur\xbb \u2014 \u0438\u0434\u0443\u0442 \u043a\u0430\u043a \u043e\u043f\u0435\u0447\u0430\u0442\u043a\u0430, \u043d\u043e \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u043d\u043e\u0435 \u043d\u0435 \u0434\u0440\u0443\u0433\u043e\u0435 \u0441\u043b\u043e\u0432\u043e: \xabschon\xbb \u0432\u043c\u0435\u0441\u0442\u043e \xabsch\xf6n\xbb \u2014 \u043e\u0448\u0438\u0431\u043a\u0430.")
B.arF=new A.ab("\u042f \u0437\u0430\u0431\u044b\u043b \u043f\u0435\u0440\u0435\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0440\u0430\u0441\u043a\u043b\u0430\u0434\u043a\u0443","\u0412\u0432\u043e\u0434 \u043a\u0438\u0440\u0438\u043b\u043b\u0438\u0446\u0435\u0439, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0440\u0430\u0441\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432 \u0438\u0441\u043a\u043e\u043c\u043e\u0435 \u0441\u043b\u043e\u0432\u043e, \u043d\u0435 \u043f\u0438\u0448\u0435\u0442\u0441\u044f \u0432 \u0436\u0443\u0440\u043d\u0430\u043b \u0432\u043e\u043e\u0431\u0449\u0435: \u044d\u0442\u043e \u043d\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u043f\u0430\u043c\u044f\u0442\u0438, \u0430 \u043f\u0440\u043e\u043c\u0430\u0445 \u043f\u043e \u043a\u043b\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u0435. \u041f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043f\u0440\u043e\u0441\u0442\u043e \u0441\u043f\u0440\u043e\u0441\u0438\u0442 \u0435\u0449\u0451 \u0440\u0430\u0437.")
B.arA=new A.ab("\u0413\u0434\u0435 \u043a\u043d\u043e\u043f\u043a\u0430 \xab\u043f\u043e\u043a\u0430\u0437\u0430\u0442\u044c \u043e\u0442\u0432\u0435\u0442\xbb?","\u0415\u0451 \u043d\u0435\u0442 \u043d\u0438 \u043d\u0430 \u043e\u0434\u043d\u043e\u0439 \u0441\u0442\u0443\u043f\u0435\u043d\u0438: \u0443\u0432\u0438\u0434\u0435\u0442\u044c \u043e\u0442\u0432\u0435\u0442 \u0434\u043e \u043f\u043e\u043f\u044b\u0442\u043a\u0438 \u2014 \u0437\u043d\u0430\u0447\u0438\u0442 \u043d\u0435 \u0432\u0441\u043f\u043e\u043c\u043d\u0438\u0442\u044c \u0435\u0433\u043e. \u041f\u0440\u043e\u043c\u0430\u0445 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u0441\u0440\u0430\u0437\u0443 \u0438 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0441\u043b\u043e\u0432\u043e \u0432 \u043a\u043e\u043d\u0435\u0446 \u0437\u0430\u043d\u044f\u0442\u0438\u044f, \u0430 \u043f\u043e\u0442\u043e\u043c \u043d\u0430 \u0437\u0430\u0432\u0442\u0440\u0430.\n\n\u041f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0438 \u2014 \u043f\u0435\u0440\u0432\u044b\u0435 \u0431\u0443\u043a\u0432\u044b, \u0440\u0443\u0441\u0441\u043a\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u2014 \u043e\u0442\u043a\u0440\u044b\u0442\u044c \u043c\u043e\u0436\u043d\u043e, \u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u044d\u0442\u043e \u0441\u0442\u0443\u043f\u0435\u043d\u0438: \u0441 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u043e\u0439 \u043d\u0430 \u044d\u043a\u0440\u0430\u043d\u0435 \u043e\u0442\u0432\u0435\u0442 \u043d\u0435 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u043f\u0440\u043e\u0439\u0434\u0435\u043d\u043d\u043e\u0439 \u0441\u0442\u0443\u043f\u0435\u043d\u044c\u044e, \u0438 \u0441\u043b\u043e\u0432\u043e \u0432\u0435\u0440\u043d\u0451\u0442\u0441\u044f \u0447\u0435\u0440\u0435\u0437 \u0447\u0430\u0441.")
B.arK=new A.ab("\u0427\u0442\u043e \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0448\u043a\u0430\u043b\u0430 \u043f\u043e\u0434 \u043e\u0442\u0432\u0435\u0442\u043e\u043c?","\u041f\u0440\u043e\u0439\u0434\u0435\u043d\u043d\u044b\u0435 \u0441\u0442\u0443\u043f\u0435\u043d\u0438, \u043e\u0442 \u043d\u0443\u043b\u044f \u0434\u043e \u0441\u0435\u043c\u0438. \u041e\u0434\u0438\u043d \u0432\u0435\u0440\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u2014 \u043e\u0434\u043d\u0430 \u0441\u0442\u0443\u043f\u0435\u043d\u044c, \u0438 \u043d\u0438\u0447\u0435\u0433\u043e \u043a\u0440\u043e\u043c\u0435: \u0448\u043a\u0430\u043b\u0430 \u043d\u0435 \u0441\u0447\u0438\u0442\u0430\u0435\u0442 \u043f\u0440\u043e\u0446\u0435\u043d\u0442\u044b \u0438 \u043d\u0435 \u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u043f\u043e\u043c\u043d\u0438\u0442\u0435 \u0432\u044b \u0441\u043b\u043e\u0432\u043e \u0438\u043b\u0438 \u043d\u0435\u0442.\n\n\u0420\u0430\u043d\u044c\u0448\u0435 \u043d\u0430 \u044d\u0442\u043e\u043c \u043c\u0435\u0441\u0442\u0435 \u0441\u0442\u043e\u044f\u043b \u0441\u0440\u043e\u043a, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0441\u0447\u0438\u0442\u0430\u043b\u0430 \u043c\u043e\u0434\u0435\u043b\u044c \u043f\u0430\u043c\u044f\u0442\u0438: \u043e\u043d\u0430 \u043e\u0431\u0435\u0449\u0430\u043b\u0430 \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c, \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u0443 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u043d\u0435 \u0431\u044b\u043b\u043e. \u0422\u0435\u043f\u0435\u0440\u044c \u0432\u0438\u0434\u043d\u043e \u0442\u043e, \u0447\u0442\u043e \u0435\u0441\u0442\u044c \u043d\u0430 \u0441\u0430\u043c\u043e\u043c \u0434\u0435\u043b\u0435 \u2014 \u043a\u0430\u043a\u0443\u044e \u0438\u0437 \u0441\u0435\u043c\u0438 \u0441\u0442\u0443\u043f\u0435\u043d\u0435\u0439 \u0432\u044b \u0437\u0430\u043a\u0440\u044b\u043b\u0438 \u0438 \u043a\u043e\u0433\u0434\u0430 \u0432\u0435\u0440\u043d\u0451\u0442\u0441\u044f \u0441\u043b\u043e\u0432\u043e.")
B.arl=new A.ab("\u041e\u0434\u043d\u0430 \u043e\u0448\u0438\u0431\u043a\u0430 \u2014 \u0432\u0441\u0451 \u043f\u0440\u043e\u043f\u0430\u043b\u043e?","\u041d\u0435\u0442. \u041f\u0440\u043e\u043c\u0430\u0445 \u043d\u0435 \u0441\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442 \u0441\u0442\u0443\u043f\u0435\u043d\u0438: \u0441\u043b\u043e\u0432\u043e \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0437\u0430\u0432\u0442\u0440\u0430. \u041e\u0434\u043d\u043e \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u2014 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u044f\u044f, \u0441\u0435\u0434\u044c\u043c\u0430\u044f: \u043e\u0448\u0438\u0431\u043a\u0430 \u043d\u0430 \u043d\u0435\u0439 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0441\u043b\u043e\u0432\u043e \u043d\u0430 \u0448\u0435\u0441\u0442\u0443\u044e, \u0430 \u0447\u0435\u0440\u0435\u0437 \u043c\u0435\u0441\u044f\u0446 \u043e\u043d\u043e \u0441\u043d\u043e\u0432\u0430 \u0432\u044b\u0445\u043e\u0434\u0438\u0442 \u043d\u0430 \u0441\u0435\u0434\u044c\u043c\u0443\u044e.")
B.arB=new A.ab("\u042f \u0438 \u0442\u0430\u043a \u0437\u043d\u0430\u044e \u044d\u0442\u043e \u0441\u043b\u043e\u0432\u043e","\u041d\u0430 \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0435 \u0437\u043d\u0430\u043a\u043e\u043c\u0441\u0442\u0432\u0430 \u0435\u0441\u0442\u044c \xab\u042f \u0443\u0436\u0435 \u0437\u043d\u0430\u044e \u044d\u0442\u043e \u0441\u043b\u043e\u0432\u043e\xbb \u2014 \u0441\u043b\u043e\u0432\u043e \u0443\u0439\u0434\u0451\u0442 \u0438\u0437 \u0438\u0437\u0443\u0447\u0435\u043d\u0438\u044f \u0441\u0440\u0430\u0437\u0443, \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0441\u043f\u0440\u0430\u0448\u0438\u0432\u0430\u044f. \u0421\u043b\u043e\u0432\u043e, \u043f\u0440\u043e\u0448\u0435\u0434\u0448\u0435\u0435 \u0432\u0441\u0435 \u0441\u0435\u043c\u044c \u0441\u0442\u0443\u043f\u0435\u043d\u0435\u0439, \u043f\u043e\u043f\u0430\u0434\u0430\u0435\u0442 \u0442\u0443\u0434\u0430 \u0441\u0430\u043c\u043e. \u0418 \u0432\u0440\u0443\u0447\u043d\u0443\u044e, \u0432 \u043b\u044e\u0431\u043e\u0439 \u043c\u043e\u043c\u0435\u043d\u0442 \u2014 \u0432 \u0441\u043b\u043e\u0432\u0430\u0440\u0435.")
